-- 2027 资料核对第十七批（公立·私立大学 19 所）。
-- 已于 2026-11-05 通过 scripts/apply-reviewed-sync-batch-17.cjs 经 Supabase REST 应用。
-- 保留为等价的可审计 SQL 工件；下方校验在任一 slug 缺失时中止。
-- 来源与限制见 docs/REDESIGN-AND-DATA.md 与 data/school-reviews.ts。
-- 受控同步：仅 19 条 University 记录按 slug upsert；无 DELETE、无批量导入、无表结构变更。
BEGIN;
DO $$ BEGIN
  IF (SELECT count(*) FROM "University" WHERE slug IN ('omu', 'tmu', 'yokohama-city', 'nagoya-city', 'sapporo-medical', 'wakayama-medical', 'hyogo', 'shizuoka-pu', 'toyama-pu', 'hama-med', 'shiga-medical', 'kansai', 'kwansei', 'tokyo-medical', 'jikei', 'juntendo', 'nms', 'fujita', 'aichi-medical')) <> 19 THEN
    RAISE EXCEPTION '本批目标学校记录缺失，已中止，未应用任何更新';
  END IF;
END $$;
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'omu', '大阪公立大学', '大阪公立大学', 'public', '公立（综合）', '大阪府大阪市（杉本/中百舌鸟/阿倍野/森之宫校区）', '官网2026年度：学部生·学域生检定料30,000日元、入学料282,000日元（大阪府民及其子女）/382,000日元（其他）、授课费535,800日元/年（前期·后期各267,900日元）；兽医学部另收实验机器充实负担金85,000日元/年与实习充实负担金100,000日元/年。', '未核实（官网未设统一GPA门槛）', '多数学部·学域的私费外国人留学生特别选抜要求EJU日语；现代系统科学域（环境社会系统学类·教育福祉学类·心理学类）另要求EJU理科或综合科目与数学合计270分以上。', '现代系统科学域（环境社会系统学类·教育福祉学类·心理学类）要求TOEFL iBT 61分以上或新量表3.5以上；其他学部·学域的英语要求按各自要项。', '2027年度私费外国人留学生特别选抜在多数学部·学域实施（医学部医学科与康复学科不设）；现代系统科学域2027年度改为2月实施，以小论文、志望理由书等面试与出愿书类综合判定；法学部个别学力检查的外语科目改为仅英语。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生特别选抜由各学部·学域分别实施，按EJU、个别学力检查、小论文、面试与出愿书类综合判定；现代系统科学域改为2月实施，法学部外语科目仅限英语。出愿与考试日程按各学部学生募集要项（本批未取得统一日程）。', NULL, 'https://www.omu.ac.jp/admissions/ug/exam_info/summary/exam2027/index.html', '["公立综合大学","多学部设私费留学生选抜","2027年2月选抜","大阪"]'::jsonb, '[{"name":"现代系统科学域","level":"undergraduate","description":"知识信息系统学类、环境社会系统学类、教育福祉学类、心理学类；2027年度私费选抜改为2月，按小论文、面试与出愿书类综合判定。","features":["4学类","EJU 270分以上","2月选抜"]},{"name":"文学部·法学部·经济学部·商学部","level":"undergraduate","description":"官网2027年度选抜一览显示四个学部均实施私费外国人留学生特别选抜；法学部个别学力检查外语仅限英语。","features":["文系学部","私费选抜"]},{"name":"理学部·工学部·农学部·兽医学部","level":"undergraduate","description":"四个学部实施私费选抜；兽医学部另收实验与实习充实负担金。","features":["理系学部","兽医学部另计负担金"]},{"name":"看护学部·生活科学部","level":"undergraduate","description":"看护学部与生活科学部实施私费选抜；具体科目与日程按学部要项。","features":["看护","生活科学"]}]'::jsonb, '["关西圈","公立大学","EJU日语路径","希望多学部选择"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'tmu', '东京都立大学', '東京都立大学', 'public', '公立（综合）', '东京都八王子市南大泽（主校区）', '官网：入学检定料17,000日元、入学料282,000日元（东京都居民141,000日元）、授课费520,800日元/年（前期·后期各260,400日元）。', '未核实（官网未设统一GPA门槛）', '2027私费外国人留学生入试以EJU成绩进行第一次选抜；各学部指定EJU科目不同，按要项确认。', '人文社会学部第一次选抜另用TOEFL iBT成绩；其他学部按要项。', '2027私费入试：出愿2026-12-07至12-09，第一次选抜2027-02-10，第二次笔试2/25-26、面试3/3，最终合格3/8；授课原则上为日语，理学部生命科学科可仅修英语授课毕业。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生入试：第一次选抜按EJU（人文社会学部另加TOEFL iBT）；第二次为学力试验与面试；出愿2026-12-07至12-09，第一次结果2027-02-10，笔试2/25-26、面试3/3，最终合格3/8。', NULL, 'https://www.tmu.ac.jp/entrance/faculty/outline/others.html', '["公立综合","东京都内","2027私费入试","部分学科可英语毕业"]'::jsonb, '[{"name":"人文社会学部·法学部","level":"undergraduate","description":"人文社会学部设人间社会学科与人文学科；法学部法学科；两学部均实施私费外国人留学生入试。","features":["人文社会","法学","第一次选抜"]},{"name":"理学部","level":"undergraduate","description":"数理科学科、物理学科、化学科、生命科学科；生命科学科可仅修英语授课毕业。","features":["4学科","生命科学科英语授课"]},{"name":"都市环境学部","level":"undergraduate","description":"都市基盘环境学科、建筑学科、环境应用化学科、都市政策科学科；2027年度入试起部分学科停止私费留学生募集。","features":["4学科","部分学科停止募集"]},{"name":"系统设计学部","level":"undergraduate","description":"情报科学科、电气电子工学科、机械系统工学科、航空宇宙系统工学科、工业设计学科。","features":["5学科","工学·设计"]},{"name":"经济经营学部","level":"undergraduate","description":"经济经营学部另设单独的私费外国人留学生入试要项与日程，需另行确认。","features":["单独日程","按要项确认"]}]'::jsonb, '["东京都内公立","人文社会/法学","理工科","可用英语完成部分学科"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'yokohama-city', '横滨市立大学', '横浜市立大学', 'public', '公立（都市型）', '神奈川县横滨市金泽区', '官网：入学料282,000日元（横滨市内出身141,000日元）加设施设备费50,000日元（市内25,000日元）；授课费557,400日元/年（2026年度实绩）。', '未核实（官网未设统一GPA门槛）', '2027私费入试要求EJU日语及学部指定科目，且各科目与日语各领域均需达到平均分以上。', 'TOEFL iBT 61分以上、TOEIC L&R 600分以上、英检准1级、GTEC 1140分以上或IELTS 5.0以上（2024年4月以后受考）。', '国际教养、国际商、理学、数据科学4学部招收私费留学生；第1期出愿2026-09-04至09-08、10月3日考试、11月2日合格发表；第2期2027-01-25至01-27、2月25日考试、3月10日发表。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027外国人留学生特别选抜：笔试（小论文或综合问题，100分）加面试（100分），英语资格按标准加分（10分）；出愿第1期2026-09-04至09-08、第2期2027-01-25至01-27。', NULL, 'https://www.yokohama-cu.ac.jp/admissions/admissions/special_selection/international_students/index.html', '["4学部","两期募集","英语资格加分","横滨"]'::jsonb, '[{"name":"国际教养学部（国际教养学科）","level":"undergraduate","description":"第1期与第2期均招生若干名；笔试为小论文，面试考察志望动机与学习意欲。","features":["两期招生","小论文+面试"]},{"name":"国际商学部（国际商学科）","level":"undergraduate","description":"第1期与第2期均招生若干名；第1期笔试为综合问题，第2期为小论文。","features":["两期招生","综合问题"]},{"name":"理学部（理学科）","level":"undergraduate","description":"第1期与第2期均招生若干名；第2期笔试为理科2科目。","features":["两期招生","理科笔试"]},{"name":"数据科学学部（数据科学学科）","level":"undergraduate","description":"仅第1期招生，第2期不招；笔试为综合问题。","features":["仅第1期","数据科学"]}]'::jsonb, '["横滨/东京圈","国际教养/商学","数据科学","EJU+英语"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'nagoya-city', '名古屋市立大学', '名古屋市立大学', 'public', '公立（都市型）', '爱知县名古屋市瑞穗区', '2026年度入学额：入学料332,000日元（名古屋市居民等232,000日元）、授课费535,800日元/年；2027年度额待校方公布。', '未核实（官网未设统一GPA门槛）', '2027私费选抜按学部利用EJU（含日语）；药学部实施两阶段选抜，第一阶段按EJU成绩。', '经济学部等按学部利用TOEIC/TOEFL等英语成绩；具体科目与分数按要项。', '药学、经济、人文社会、理学4学部招收私费留学生；出愿2026-11-01至11-06、选抜2026-11-28、合格发表2026-12-08。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生选抜按学部实施：药学部两阶段（EJU后面试）；经济学部按EJU与英语；人文社会学部与理学部按EJU、英语及面试等综合。出愿2026-11-01至11-06，选抜2026-11-28，合格发表2026-12-08。', NULL, 'https://www.nagoya-cu.ac.jp/admissions/undergraduate/guide/', '["4学部","11月选抜","名古屋市","公立"]'::jsonb, '[{"name":"药学部","level":"undergraduate","description":"药学科（6年制）与生命药科学科（4年制），各若干名；实施两阶段选抜，第一阶段按EJU成绩。","features":["6年制/4年制","两阶段选抜"]},{"name":"经济学部（经济经营学科）","level":"undergraduate","description":"若干名；按EJU与英语成绩等综合判定。","features":["经济经营","按学部要项"]},{"name":"人文社会学部","level":"undergraduate","description":"心理教育学科（教育学/心理学课程）、现代社会学科、国际文化学科；其中国际文化学科3名。","features":["3学科","国际文化3名"]},{"name":"理学部（理学科）","level":"undergraduate","description":"若干名；按EJU、英语及面试等综合判定。","features":["理学","按学部要项"]}]'::jsonb, '["名古屋/中部圈","药学","人文社会","公立"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'sapporo-medical', '札幌医科大学', '札幌医科大学', 'public', '公立（医科）', '北海道札幌市中央区', '官网：入学料282,000日元、授课费535,800日元/年（4月与10月两期）；教科书等约80,000至100,000日元。', '未核实（官网未设统一GPA门槛）', '2027私费选抜要求EJU日语（含记述）360分以上；医学部数学与理科合计320分以上，保健医疗学部280分以上（按令和8年度要项，2027年度要项为准）。', '未设统一英语分数门槛；医学部个别学力检查含英语笔试。', '医学部医学科与保健医疗学部（看护/理学疗法/作业疗法）设私费外国人留学生选抜，各若干名；2027年度考试日2027-02-25。', '研究生制度以研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生选抜：医学部按EJU、个别学力检查（英语·数学·理科）与个人面试；保健医疗学部按EJU、个人面试与出愿书类。全部以日语实施，考试日2027-02-25。', NULL, 'https://web.sapmed.ac.jp/jp/public/exam/l0re8300000007s0.html', '["医学部","保健医疗学部","私费留学生选抜","札幌"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"若干名；按EJU、一般选抜前期第二次试验（个别学力检查·个人面试）与出愿书类综合判定。","features":["若干名","个别学力检查"]},{"name":"保健医疗学部","level":"undergraduate","description":"看护学科、理学疗法学科、作业疗法学科，各若干名；按EJU、个人面试与出愿书类判定。","features":["3学科","个人面试"]}]'::jsonb, '["医学","看护/康复","北海道","EJU高分"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'wakayama-medical', '和歌山县立医科大学', '和歌山県立医科大学', 'public', '公立（医科）', '和歌山县和歌山市', '官网：授课费535,800日元/年；入学料医学部县内282,000日元/县外752,000日元，保健看护学部282,000/423,000日元，药学部282,000/564,000日元。', '未核实（官网未设统一GPA门槛）', '本次核对未发现外国人留学生专用学部选抜；学校推荐型与一般选抜以日本国内高中课程为对象。', '无外国人留学生专用学部选抜，未设统一英语门槛。', '2027年度学部选抜为学校推荐型（出愿12/15-12/22、面试2/7、合格2/9）与一般选抜前期（出愿1/25-2/3、考试2/25-26、合格3/9）；本次核对未发现外国人留学生专用学部选抜。', '研究生制度以研究科要项为准；本批未逐科核实受理条件。', '无外国人留学生专用学部选抜；持日本高中毕业资格者可参加学校推荐型（出愿2026-12-15至12-22、面试2027-02-07、合格2027-02-09）或一般选抜前期（出愿2027-01-25至02-03、考试2/25-26、合格3/9）。', NULL, 'https://www.wakayama-med.ac.jp/nyushi/gakuhi/', '["医学部","保健看护学部","药学部","仅日本国内选抜路径"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"2027年度以学校推荐型与一般选抜前期招生；未设外国人留学生专用选抜。","features":["学校推荐型","一般前期"]},{"name":"保健看护学部看护学科","level":"undergraduate","description":"入学料县内282,000/县外423,000日元；选抜按一般与推荐要项。","features":["看护","县内外入学料不同"]},{"name":"药学部药学科","level":"undergraduate","description":"6年制；入学料县内282,000/县外564,000日元。","features":["6年制药学","县内外入学料不同"]}]'::jsonb, '["日本国内高中毕业","医学/看护/药学","和歌山"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'hyogo', '兵库县立大学', '兵庫県立大学', 'public', '公立（综合）', '兵库县神户市（神户商科）/姬路市（工学）等', '入学料282,000日元、授课费535,800日元/年（2027年度预定，以要项为准）。', '未核实（官网未设统一GPA门槛）', '2027外国人留学生特别选抜要求EJU日语及学部指定科目；国际商经（经济/经营）与社会信息科学为日语、理科或综合科目、数学三教科。', '国际商经学部全球商务课程要求CEFR B2（IELTS 5.5、TOEFL iBT 72、TOEIC L&R+S&W 1560等）；其他学部按要项。', '2027外国人留学生特别选抜：国际商经（经济/经营）与社会信息科学出愿1/15-22、考试2/25、合格3/7；工学部出愿1/25-2/3、考试2/25、合格3/7；全球商务课程为2027年9月入学、30名、全英语。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027外国人留学生特别选抜：不设共通测试，按本校学力检查（数学与英语，或数学与日语小论文）、面试、EJU成绩与出愿书类综合判定；国际商经/社会情报1/15-22出愿，工学部1/25-2/3出愿。', NULL, 'https://www.u-hyogo.ac.jp/hyogoon/admissions/guideline/', '["6学部","9月入学英语课程","外国人留学生特别选抜","兵库"]'::jsonb, '[{"name":"国际商经学部","level":"undergraduate","description":"国际商经学科（经济学课程·经营学课程）若干名；全球商务课程30名，2027年9月入学，全英语。","features":["经济/经营","全球商务9月入学"]},{"name":"社会情报科学部","level":"undergraduate","description":"社会情报科学科若干名；出愿1/15-22、考试2/25、合格3/7。","features":["数据/情报","2月选抜"]},{"name":"工学部","level":"undergraduate","description":"工学科含电气电子、知能情报、机械、材料设计、化学等课程，若干名；出愿1/25-2/3。","features":["5课程","工学"]},{"name":"理学部","level":"undergraduate","description":"物质科学科、生命科学科；实施外国人留学生特别选抜。","features":["2学科","理学"]},{"name":"环境人间学部·看护学部","level":"undergraduate","description":"环境人间学部设环境人间、建筑地域设计、绿色科学、食环境营养学科；看护学部看护学科；均设外国人留学生特别选抜。","features":["环境人间","看护"]}]'::jsonb, '["关西圈","商经/国际商务","工学","英语授课课程"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'shizuoka-pu', '静冈县立大学', '静岡県立大学', 'public', '公立（县立）', '静冈县静冈市骏河区', '官网：入学料366,600日元（静冈县内141,000日元）、授课费535,800日元/年（以上为2026年度入学者额，2027年度以入学手续要项为准）。', '未核实（官网未设统一GPA门槛）', '2027私费选抜利用EJU；国际关系学部另考日语，其他学部按学部指定科目。', '药学部、食品营养科学部、经营情报学部利用TOEFL iBT或TOEIC L&R；国际关系学部以英语与日语学力检查为主。', '2027私费选抜出愿2026-12-22至2027-01-07（12/26-1/3除外）；食品营养、国际关系、经营情报2/25考试，药学部3/8考试；合格发表分别3/6与3/21。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生选抜按学部：药学部（物理·化学笔试、EJU、TOEFL/TOEIC、面试，3/8）；食品营养（化学笔试、面试、EJU、英语，2/25）；国际关系（英语·日语、面试，2/25）；经营情报（书类、EJU、英语、面试，2/25）。', NULL, 'https://www.u-shizuoka-ken.ac.jp/admissions/faculty/guide/f-request/', '["5学部","2月/3月考试","公立","静冈"]'::jsonb, '[{"name":"药学部","level":"undergraduate","description":"药科学科（4年制）与药学科（6年制），各若干名；3/8考试，按物理·化学笔试、EJU、英语与面试。","features":["4年制/6年制","3月8日考试"]},{"name":"食品营养科学部","level":"undergraduate","description":"食品生命科学科、营养生命科学科、环境生命科学科各若干名；2/25考试，按化学笔试、面试、EJU与英语。","features":["3学科","2月25日考试"]},{"name":"国际关系学部","level":"undergraduate","description":"国际关系学科、国际语言文化学科各若干名；2/25考试，按英语与日语学力检查及面试。","features":["2学科","英语+日语"]},{"name":"经营情报学部","level":"undergraduate","description":"经营情报学科若干名；2/25考试，按出愿书类、EJU、英语与面试（合计500分）。","features":["经营情报","合计500分"]},{"name":"看护学部","level":"undergraduate","description":"看护学科不设私费外国人留学生选抜。","features":["不设私费选抜"]}]'::jsonb, '["静冈","药学/食品营养","国际关系","经营情报"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'toyama-pu', '富山县立大学', '富山県立大学', 'public', '公立（工科系）', '富山县射水市', '官网：入学考查料17,000日元、入学料188,000日元（富山县居民）/282,000日元、授课费267,900日元/学期（年额535,800日元）。', '未核实（官网未设统一GPA门槛）', '2027私费外国人留学生入试（综合型选抜）的EJU科目要求按要项；本批未取得具体科目。', '未取得统一英语门槛；按2027年度私费外国人留学生入试要项确认。', '工学部5学科与情报工学部3学科设私费外国人留学生入试，各学科若干名；看护学部不设该选抜；2027年度私费外国人留学生入试（综合型选抜）募集要项已于2026-09-14公表。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '2027私费外国人留学生入试以综合型选抜实施；出愿、考试与选考方法按2027年度私费外国人留学生入试（综合型选抜）募集要项。', NULL, 'https://www.pu-toyama.ac.jp/campus_life/support/for_international_students/', '["工学部5学科","情报工学部3学科","综合型选抜","富山"]'::jsonb, '[{"name":"工学部","level":"undergraduate","description":"机械系统工学科、电气电子工学科、环境·社会基盘工学科、生物工学科、医药品工学科；各学科私费外国人留学生入试若干名。","features":["5学科","各若干名"]},{"name":"情报工学部","level":"undergraduate","description":"数据科学学科、情报系统工学科、智能机器人工学科；各学科私费外国人留学生入试若干名。","features":["3学科","各若干名"]},{"name":"看护学部","level":"undergraduate","description":"看护学科不设私费外国人留学生入试。","features":["不设私费入试"]}]'::jsonb, '["工科/情报","北陆圈","综合型选抜","富山"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'hama-med', '浜松医科大学', '浜松医科大学', 'national', '国立（医科）', '静冈县滨松市中央区', '官网：入学料282,000日元、授课费535,800日元/年（前期·后期各267,900日元）。', '未核实（官网未设统一GPA门槛）', '本次核对未在官网确认外国人留学生专用学部选抜；学部选抜以日本国内高中课程为对象。', '无外国人留学生专用学部选抜，未设统一英语门槛。', '医学部医学科与看护学科；2027年度学部选抜为一般、学校推荐型、海外教育项目特别选抜、社会人入试；留学生支援（日语补讲、奖学金）面向在读留学生。', '研究生与大学院按各研究科要项；国际中心为在读留学生提供日语补讲、生活与奖学金支援。', '无外国人留学生专用学部选抜；按一般选抜、学校推荐型、海外教育项目特别选抜、社会人入试各自要项。', NULL, 'https://www.hama-med.ac.jp/admission/gakuhi.html', '["医学部","看护学科","国立","留学生支援"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"2027年度按一般·学校推荐型等选抜招生；未设外国人留学生专用学部选抜。","features":["6年制","一般/推荐"]},{"name":"医学部看护学科","level":"undergraduate","description":"2027年度按一般·学校推荐型等选抜招生；未设外国人留学生专用学部选抜。","features":["看护","一般/推荐"]}]'::jsonb, '["医学/看护","日本国内高中毕业","静冈"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'shiga-medical', '滋贺医科大学', '滋賀医科大学', 'national', '国立（医科）', '滋贺县大津市', '官网：学部入学检定料17,000日元、入学料282,000日元、授课费535,800日元/年；研究生检定料9,800、入学料84,600、授课费28,900日元/月。', '未核实（官网未设统一GPA门槛）', '外国人留学生仅通过大学院（医学专攻博士课程、看护学专攻博士前期·后期课程）与研究生接收；学部未设外国人专用选抜。', '未设学部外国人专用选抜；大学院按研究科入试要求。', '学部为医学部医学科与看护学科；官网《外国人留学生の手引き》列出的留学生区分仅为大学院学生与研究生，未列学部私费留学生选抜。', '研究生：检定料9,800日元、入学料84,600日元、授课费28,900日元/月；需指导教員同意。', '学部无外国人专用选抜；大学院按医学专攻、看护学专攻各自入试要项实施。', NULL, 'https://www.shiga-med.ac.jp/international/guidance', '["医学部","看护学科","留学生仅大学院/研究生","滋贺"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"学部未设外国人留学生专用选抜；外国人留学生经大学院医学专攻博士课程接收。","features":["6年制","无学部留学生选抜"]},{"name":"医学部看护学科","level":"undergraduate","description":"学部未设外国人留学生专用选抜；大学院看护学专攻设博士前期·后期课程。","features":["看护","大学院接收"]},{"name":"大学院医学系研究科","level":"graduate","description":"医学专攻博士课程、看护学专攻博士前期·后期课程；私费留学生可报考。","features":["博士课程","私费留学生"]}]'::jsonb, '["大学院医学研究","看护学研究","研究生","滋贺"]'::jsonb
