INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'kansai', '关西大学', '関西大学', 'private', '私立（综合）', '大阪府吹田市', '2027年度学杂费未定；2026年度参考：入学金260,000日元，授课料495,000日元/学期（文系学部）、681,000日元/学期（综合情报·社会安全·商务数据科学学部）。', '未核实（官网未设统一GPA门槛）', '2027外国人学部留学生入试要求EJU（学部指定科目）；未设统一JLPT等级。', '文学部、经济学部、商学部、社会学部、人间健康学部、商务数据科学学部需提交TOEFL iBT或TOEIC L&R等英语成绩；社会学部另设IELTS 3.5、TOEFL iBT 2.5（旧量表37分）、TOEIC L&R 420分的出愿最低线。', '2027外国人学部留学生入试分9月募集与11月募集：9月出愿9/1-9/7、10/18选抜、11/2发表；11月出愿11/13-11/19、2027-01-10选抜、01-15发表；检定料35,000日元。', '研究生制度以各研究科要项为准；本批未逐科核实受理条件与是否需要教授内诺。', '9月募集：法学部仅书类审查，文学部·经济学部·社会学部·综合情报学部10/18选抜；11月募集：文学部·商学部·人间健康学部·商务数据科学学部2027-01-10选抜，其余学部仅书类。', NULL, 'https://www.nyusi.kansai-u.ac.jp/admission/foreigner/', '["13学部","9月/11月两期","EJU+英语","大阪"]'::jsonb, '[{"name":"法学部·文学部·经济学部·商学部","level":"undergraduate","description":"9月募集与11月募集分别设名额；法学部9月仅书类审查，文学部9月10/18选抜，商学部11月2027-01-10选抜。","features":["文系","两期募集"]},{"name":"社会学部·政策创造学部·人间健康学部","level":"undergraduate","description":"社会学部9月5名并参加10/18选抜；政策创造与人间健康在11月募集。","features":["社会学","政策/人间健康"]},{"name":"综合情报学部·社会安全学部·商务数据科学学部","level":"undergraduate","description":"综合情报9月5名；社会安全与商务数据科学在11月募集，商务数据科学10名。","features":["情报","数据科学"]},{"name":"系统理工学部·环境都市工学部·化学生命工学部","level":"undergraduate","description":"11月募集，均为若干名，仅书类审查。","features":["理工科","书类审查"]}]'::jsonb, '["关西圈","文系/理系","9月或11月出愿","EJU+英语"]'::jsonb
