INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'fujita', '藤田医科大学', '藤田医科大学', 'private', '私立（医科）', '爱知县丰明市', '医学科2027年度：入学金1,500,000、授课2,000,000、实验实习教材500,000、教育充实920,000（初年度合计4,920,000）；2年级以后3,320,000日元/年，6年合计22,126,000日元。医工共创学科930,000日元（就学支援金后）；医疗科学部1,650,000；保健卫生学部1,700,000。', '未核实（官网未设统一GPA门槛）', '本次核对未发现面向外国籍留学生的学部选抜；归国生·国际文凭选抜要求日本国籍或永住许可。', '归国生·国际文凭选抜需TOEFL iBT或IELTS Academic；外国籍无永住者不可报考该选抜。', '医学部（医学科/医工共创学科）、医疗科学部、保健卫生学部；2027年度未设私费外国人留学生选抜，归国生·国际文凭选抜限日本国籍或永住者。', '研究生与大学院按研究科要项；本批未逐科核实受理条件。', '无外国人留学生专用选抜；医学科按ふじた未来入试、归国生·国际文凭入试、一般入试、共通测试利用入试实施。', NULL, 'https://www.fujita-hu.ac.jp/admission/', '["医学部","医疗科学部","保健卫生学部","归国生选抜限国籍"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"2027年度初年度4,920,000日元、2年级以后3,320,000日元，6年合计22,126,000日元；未设私费留学生选抜。","features":["6年制","初年度492万日元"]},{"name":"医学部医工共创学科","level":"undergraduate","description":"学纳金930,000日元（就学支援金400,000日元支给后）。","features":["医工共创","就学支援金"]},{"name":"医疗科学部·保健卫生学部","level":"undergraduate","description":"医疗科学部初年度1,650,000日元；保健卫生学部（看护/康复）初年度1,700,000日元。","features":["医疗科学","保健卫生"]}]'::jsonb, '["医学/医疗科学","日本国籍或永住","爱知"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
INSERT INTO "University" (slug, "name", "nameJa", "type", "ranking", "location", "tuition", "gpaRequirement", "japaneseRequirement", "englishRequirement", "highlights", "researchStudent", "examFormat", "sguNote", "website", "featuresJson", "programsJson", "suitableForJson") VALUES (
  'aichi-medical', '爱知医科大学', '愛知医科大学', 'private', '私立（医科）', '爱知县长久手市', '医学科：入学金1,500,000、授课1,500,000/学期（年3,000,000）、教育充实2,700,000、设施维持500,000；初年度8,200,000、2年级以后5,200,000日元。看护学部初年度1,760,000、以后1,540,000日元。', '未核实（官网未设统一GPA门槛）', '外国にルーツを持つ生徒特別選抜要求JLPT N2以上（本年度未取得者可报考）；该选抜以在日本居住者为对象。', '该选抜无统一英语门槛；按基础学力试验（数学·英语）、小论文与面试综合评价。', '医学部医学科设「外国にルーツを持つ生徒特別選抜」：限外国籍或归化6年以内、在留累计9年以内、非留学/短期滞在、日本高中毕业、有科学奥林匹克成绩、JLPT N2；出愿2026-11-01至11-13、考试11-28、合格12-10。', '研究生与大学院按研究科要项；本批未逐科核实受理条件。', '外国にルーツを持つ生徒特別選抜：科学奥林匹克成绩、基础学力试验（数学·英语）、小论文、面试与书类综合判定；事前审查截止2026-10-09，出愿2026-11-01至11-13，考试11-28。', NULL, 'https://www.aichi-med-u.ac.jp/su11/su1108/su110801/index.html', '["医学部","外国にルーツ選抜","需在日居住","爱知"]'::jsonb, '[{"name":"医学部医学科","level":"undergraduate","description":"2027年度初年度8,200,000日元、2年级以后5,200,000日元；设外国にルーツを持つ生徒特別選抜（若干名）。","features":["6年制","外国にルーツ选抜"]},{"name":"看护学部看护学科","level":"undergraduate","description":"初年度1,760,000日元、2年级以后1,540,000日元；按一般、推荐、社会人等选抜。","features":["看护","初年度176万日元"]}]'::jsonb, '["在日外国根学生","医学","日本高中毕业"]'::jsonb
) ON CONFLICT (slug) DO UPDATE SET "nameJa" = EXCLUDED."nameJa", "type" = EXCLUDED."type", "ranking" = EXCLUDED."ranking", "location" = EXCLUDED."location", "tuition" = EXCLUDED."tuition", "gpaRequirement" = EXCLUDED."gpaRequirement", "japaneseRequirement" = EXCLUDED."japaneseRequirement", "englishRequirement" = EXCLUDED."englishRequirement", "highlights" = EXCLUDED."highlights", "researchStudent" = EXCLUDED."researchStudent", "examFormat" = EXCLUDED."examFormat", "sguNote" = EXCLUDED."sguNote", "website" = EXCLUDED."website", "featuresJson" = EXCLUDED."featuresJson", "programsJson" = EXCLUDED."programsJson", "suitableForJson" = EXCLUDED."suitableForJson";
COMMIT;
